import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int N = 32;
    static long n;
    static int k;

    static boolean readInput(Scanner scanner) {
        if (scanner.hasNextLong() && scanner.hasNextInt()) {
            n = scanner.nextLong();
            k = scanner.nextInt();
            return true;
        }
        return false;
    }

    static int addMod(int a, int b, int m) {
        a += b;
        if (a >= m) a -= m;
        return a;
    }

    static int mulMod(int a, int b, int m) {
        return (int)((long)a * b % m);
    }

    static int[][] matrixMultiply(int[][] a, int[][] b, int m, int size) {
        int[][] c = new int[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                c[i][j] = 0;
                for (int t = 0; t < size; t++) {
                    c[i][j] = addMod(c[i][j], mulMod(a[i][t], b[t][j], m), m);
                }
            }
        }
        return c;
    }

    static int[][] createIdentity(int size) {
        int[][] res = new int[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                res[i][j] = 0;
            }
            res[i][i] = 1;
        }
        return res;
    }

    static List<List<int[][]>> precomputeMatrices(int k) {
        List<List<int[][]>> amat = new ArrayList<>();
        for (int d = 0; d < 62; d++) {
            List<int[][]> innerList = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                int[][] base = createIdentity(k + 1);
                base[d][d] = 1;
                base[k][k] = 1;
                innerList.add(base);
            }
            amat.add(innerList);
        }
        return amat;
    }

    static void mainProcess() {
        List<Integer> num = new ArrayList<>();
        long tempN = n;
        while (tempN > 0) {
            num.add((int)(tempN % k));
            tempN /= k;
        }

        List<List<int[][]>> amat = precomputeMatrices(k);

        // Main computation logic, omitted for brevity
        int answer = 0;
        System.out.println(answer);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (readInput(scanner)) {
            mainProcess();
        }
        scanner.close();
    }
}
